        "component_id": "comp_control_board",
        "name": "Control board",
        "description": "A board mounted in the front panel; it connects to the power board by a ribbon cable.",
        "category": "control"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "A board in the power supply with MOSFET and diode components mounted against the heatsink using thermal strips and clips.",
        "category": "control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "A board in the power supply connected to the control board and the TORCH START connector.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "The assembly that houses the control board, compressor-driver board, and power board.",
        "category": "electrical"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "The panel that holds the control board and amperage adjustment knob.",
        "category": "structural"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "The cover fitted over the power supply.",
        "category": "structural"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "A barrier installed within the power supply.",
        "category": "structural"
      },
      {
        "component_id": "comp_heatsink",
        "name": "Heatsink",
        "description": "A heatsink that supports thermal strips beneath the compressor-driver board's MOSFET and diode.",
        "category": "thermal"
      },
      {
        "component_id": "comp_mosfet",
        "name": "MOSFET",
        "description": "A component on the compressor-driver board that sits on a thermal strip against the heatsink and is covered by a clip.",
        "category": "electronic"
      },
      {
        "component_id": "comp_diode",
        "name": "Diode",
        "description": "A component on the compressor-driver board that sits on a thermal strip against the heatsink and is covered by a clip.",
        "category": "electronic"
      },
      {
        "component_id": "comp_ribbon_cable",
        "name": "Ribbon cable",
        "description": "A cable connecting the control board to the power board at J7.",
